from pathlib import Path, PurePosixPath
import base64, hashlib, io, json, os, pwd, zipfile
root=Path('/data1/home/sunyiq/kalmannet_thirteen_basin_forecast_comparison_20261005_attempt1')
if pwd.getpwuid(os.getuid()).pw_name!='sunyiq': raise RuntimeError('wrong account')
for p in (root,*root.parents):
 if p.is_symlink(): raise RuntimeError('linked destination')
raw=base64.b64decode('',validate=True)
if hashlib.sha256(raw).hexdigest()!='6da09345a281c082c434126ecbe3123f21aab2ff62f0da8b1baa2b4122755b9c': raise RuntimeError('archive identity mismatch')
root.mkdir(exist_ok=False)
with zipfile.ZipFile(io.BytesIO(raw)) as z:
 for i in z.infolist():
  p=PurePosixPath(i.filename)
  if p.is_absolute() or '..' in p.parts or '\\' in i.filename or ':' in i.filename or i.is_dir(): raise RuntimeError('unsafe archive')
  dest=root/i.filename; dest.parent.mkdir(parents=True,exist_ok=True)
  with dest.open('xb') as f:f.write(z.read(i))
for d in ['control','logs','cache','tmp']: (root/d).mkdir(exist_ok=False)
m=json.loads((root/'payload_manifest.json').read_text())
a=json.loads((root/'implementation_admission.json').read_text())
if a['payload_manifest_sha256']!=hashlib.sha256((root/'payload_manifest.json').read_bytes()).hexdigest(): raise RuntimeError('unreviewed deployment')
for name,record in m['files'].items():
 p=root/name
 if record!={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'size_bytes':p.stat().st_size}: raise RuntimeError('member mismatch')
record={'stage_id':m['stage_id'],'archive_sha256':'6da09345a281c082c434126ecbe3123f21aab2ff62f0da8b1baa2b4122755b9c','manifest_sha256':a['payload_manifest_sha256'],'status':'FRESH_ISOLATED_DEPLOYMENT_NO_SUBMISSION'}
with (root/'control/deployment.json').open('x') as f:json.dump(record,f,sort_keys=True)
print('FORECAST13_DEPLOYMENT '+json.dumps(record,sort_keys=True),flush=True)
FORECAST13_DEPLOY_PY
